create extension if not exists pgcrypto;
create type work_order_status as enum ('Pending Plan','Scheduled','In Progress','Completed','Diverted');
create type uom_type as enum ('Pcs','Mtrs');
create type qa_status as enum ('Pending','Cleared','Hold','Rejected');
create type app_role as enum ('Admin','PPC','Production','QA','Viewer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role app_role not null default 'Viewer', created_at timestamptz not null default now());
create table public.process_stages(id uuid primary key default gen_random_uuid(),stage_code text unique not null,stage_name text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.process_routes(id uuid primary key default gen_random_uuid(),route_code text unique not null,route_name text not null,material_category text not null,active boolean not null default true,created_at timestamptz not null default now());
create table public.route_stages(id uuid primary key default gen_random_uuid(),route_id uuid not null references process_routes(id) on delete cascade,stage_id uuid not null references process_stages(id),sequence_no int not null check(sequence_no>0),is_required boolean not null default true,created_at timestamptz not null default now(),unique(route_id,stage_id),unique(route_id,sequence_no));
create table public.work_orders(id uuid primary key default gen_random_uuid(),work_order_no text unique not null,customer_name text,size_od numeric check(size_od>0),size_wt numeric check(size_wt>0),grade text,ordered_qty numeric not null check(ordered_qty>0),uom uom_type not null,target_date date,status work_order_status not null default 'Pending Plan',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.rolling_plans(id uuid primary key default gen_random_uuid(),plan_no text unique not null default ('RP-'||to_char(clock_timestamp(),'YYYYMMDDHH24MISSMS')),work_order_id uuid not null references work_orders(id),planned_rolling_date date not null,planned_qty numeric not null check(planned_qty>0),process_route_id uuid not null references process_routes(id),target_mother_size text,status text not null default 'Scheduled',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.diversion_plans(id uuid primary key default gen_random_uuid(),source_wo_id uuid not null references work_orders(id),target_wo_id uuid not null references work_orders(id),diverted_qty numeric not null check(diverted_qty>0),process_route_id uuid not null references process_routes(id),reason text not null,approved_by uuid references auth.users(id),diversion_date date not null,created_at timestamptz not null default now(),check(source_wo_id<>target_wo_id));
create table public.production_logs(id uuid primary key default gen_random_uuid(),work_order_id uuid not null references work_orders(id),rolling_plan_id uuid references rolling_plans(id),stage_id uuid not null references process_stages(id),process_route_id uuid not null references process_routes(id),process_date date not null,input_qty numeric not null default 0 check(input_qty>=0),output_qty numeric not null default 0 check(output_qty>=0),rejection_qty numeric not null default 0 check(rejection_qty>=0),heat_lot_no text,qa_clearance qa_status,remarks text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),check(rejection_qty<=input_qty));
create table public.audit_log(id bigint generated always as identity primary key,user_id uuid references auth.users(id),action text not null,entity text not null,record_id uuid,old_value jsonb,new_value jsonb,created_at timestamptz not null default now());
create index on work_orders(status); create index on work_orders(target_date); create index on work_orders(grade); create index on work_orders(customer_name); create index on rolling_plans(work_order_id,process_route_id); create index on production_logs(work_order_id,process_route_id,stage_id,process_date); create index on diversion_plans(source_wo_id,target_wo_id);
insert into process_stages(stage_code,stage_name) values ('ROLLING','Rolling'),('HOLLOW_HEAT_TREATMENT','Hollow Heat Treatment'),('DRAW','Draw'),('HEAT_TREATMENT','Heat Treatment'),('FINISHING','Finishing') on conflict do nothing;
insert into process_routes(route_code,route_name,material_category) values ('HFS','Standard HFS','Standard'),('CDS','Standard CDS','Standard'),('ALLOY_HFS','Alloy HFS','Alloy'),('ALLOY_CDS','Alloy CDS','Alloy') on conflict do nothing;
insert into route_stages(route_id,stage_id,sequence_no) select r.id,s.id,x.seq from (values('HFS','ROLLING',1),('HFS','FINISHING',2),('CDS','ROLLING',1),('CDS','DRAW',2),('CDS','HEAT_TREATMENT',3),('CDS','FINISHING',4),('ALLOY_HFS','ROLLING',1),('ALLOY_HFS','HOLLOW_HEAT_TREATMENT',2),('ALLOY_HFS','FINISHING',3),('ALLOY_CDS','ROLLING',1),('ALLOY_CDS','HOLLOW_HEAT_TREATMENT',2),('ALLOY_CDS','DRAW',3),('ALLOY_CDS','HEAT_TREATMENT',4),('ALLOY_CDS','FINISHING',5)) x(code,stage,seq) join process_routes r on r.route_code=x.code join process_stages s on s.stage_code=x.stage on conflict do nothing;
create or replace function set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger work_orders_updated before update on work_orders for each row execute function set_updated_at();
create trigger rolling_plans_updated before update on rolling_plans for each row execute function set_updated_at();
create or replace function get_unplanned_qty(p_work_order_id uuid) returns numeric language sql security definer set search_path=public as $$ select greatest(0,w.ordered_qty-coalesce((select sum(planned_qty) from rolling_plans where work_order_id=p_work_order_id),0)-coalesce((select sum(diverted_qty) from diversion_plans where source_wo_id=p_work_order_id),0)); $$;
create or replace function create_rolling_plan(p_work_order_id uuid,p_planned_qty numeric,p_rolling_date date,p_route_id uuid,p_target_mother_size text) returns text language plpgsql security invoker set search_path=public as $$ declare n text; avail numeric; begin if p_planned_qty<=0 then raise exception 'Planned quantity must be positive'; end if; if not exists(select 1 from work_orders where id=p_work_order_id) then raise exception 'Work Order not found'; end if; if not exists(select 1 from process_routes where id=p_route_id and active) then raise exception 'Invalid route'; end if; select get_unplanned_qty(p_work_order_id) into avail; if p_planned_qty>avail then raise exception 'Planned quantity % exceeds unplanned quantity %',p_planned_qty,avail; end if; insert into rolling_plans(work_order_id,planned_rolling_date,planned_qty,process_route_id,target_mother_size) values(p_work_order_id,p_rolling_date,p_planned_qty,p_route_id,p_target_mother_size) returning plan_no into n; update work_orders set status='Scheduled' where id=p_work_order_id and status='Pending Plan'; return n; end $$;
create or replace function record_production(p_work_order_id uuid,p_route_id uuid,p_stage_code text,p_process_date date,p_input_qty numeric,p_output_qty numeric,p_rejection_qty numeric,p_heat_lot_no text,p_remarks text) returns uuid language plpgsql security invoker set search_path=public as $$ declare sid uuid; rid uuid; prev_wip numeric; seq int; prev_seq int; rec uuid; begin if p_input_qty<0 or p_output_qty<0 or p_rejection_qty<0 then raise exception 'Quantities cannot be negative'; end if; if p_rejection_qty>p_input_qty then raise exception 'Rejection cannot exceed input'; end if; select id into rid from process_routes where id=p_route_id and active; if rid is null then raise exception 'Invalid route'; end if; select ps.id,rs.sequence_no into sid,seq from route_stages rs join process_stages ps on ps.id=rs.stage_id where rs.route_id=rid and ps.stage_code=p_stage_code and rs.is_required; if sid is null then raise exception 'Stage is not part of selected route'; end if; if seq>1 then select coalesce(sum(output_qty-rejection_qty),0)-coalesce(sum(input_qty),0) into prev_wip from production_logs pl join route_stages prs on prs.stage_id=pl.stage_id and prs.route_id=pl.process_route_id where pl.work_order_id=p_work_order_id and pl.process_route_id=rid and prs.sequence_no=seq-1; if p_input_qty>greatest(prev_wip,0) then raise exception 'Insufficient WIP at previous stage. Available %, requested %',greatest(prev_wip,0),p_input_qty; end if; end if; if seq=1 and p_input_qty>get_unplanned_qty(p_work_order_id)+coalesce((select sum(planned_qty) from rolling_plans where work_order_id=p_work_order_id and process_route_id=rid),0) then raise exception 'Input exceeds available planned/order quantity'; end if; insert into production_logs(work_order_id,stage_id,process_route_id,process_date,input_qty,output_qty,rejection_qty,heat_lot_no,remarks,created_by) values(p_work_order_id,sid,rid,p_process_date,p_input_qty,p_output_qty,p_rejection_qty,p_heat_lot_no,p_remarks,auth.uid()) returning id into rec; update work_orders set status='In Progress' where id=p_work_order_id and status in ('Pending Plan','Scheduled'); return rec; end $$;
create or replace function create_diversion(p_source uuid,p_target uuid,p_qty numeric,p_route uuid,p_reason text,p_date date) returns uuid language plpgsql security invoker set search_path=public as $$ declare avail numeric; idd uuid; begin if p_source=p_target then raise exception 'Source and target WO cannot be same'; end if; if p_qty<=0 then raise exception 'Diversion quantity must be positive'; end if; select get_unplanned_qty(p_source) into avail; if p_qty>avail then raise exception 'Diversion exceeds available source quantity'; end if; if not exists(select 1 from process_routes where id=p_route and active) then raise exception 'Invalid route'; end if; if trim(coalesce(p_reason,''))='' then raise exception 'Reason is required'; end if; insert into diversion_plans(source_wo_id,target_wo_id,diverted_qty,process_route_id,reason,approved_by,diversion_date) values(p_source,p_target,p_qty,p_route,p_reason,auth.uid(),p_date) returning id into idd; return idd; end $$;
create or replace view vw_route_stage_wip as with balances as (select work_order_id,process_route_id,stage_id,sum(input_qty) input_qty,sum(output_qty) output_qty,sum(rejection_qty) rejection_qty from production_logs group by 1,2,3) select wo.id work_order_id,wo.work_order_no,r.id route_id,r.route_code,s.id stage_id,s.stage_name,rs.sequence_no,coalesce(b.input_qty,0) input_qty,coalesce(b.output_qty,0) output_qty,coalesce(b.rejection_qty,0) rejection_qty,greatest(coalesce(b.output_qty,0)-coalesce(b.input_qty,0)-coalesce(b.rejection_qty,0),0) current_wip from work_orders wo join rolling_plans rp on rp.work_order_id=wo.id join process_routes r on r.id=rp.process_route_id join route_stages rs on rs.route_id=r.id join process_stages s on s.id=rs.stage_id left join balances b on b.work_order_id=wo.id and b.process_route_id=r.id and b.stage_id=s.id group by wo.id,wo.work_order_no,r.id,r.route_code,s.id,s.stage_name,rs.sequence_no,b.input_qty,b.output_qty,b.rejection_qty;
create or replace view vw_work_order_summary as select wo.id work_order_id,wo.work_order_no,wo.customer_name customer,wo.size_od od,wo.size_wt wt,wo.grade,wo.ordered_qty,coalesce(sum(rp.planned_qty),0) planned_qty,coalesce((select sum(output_qty) from production_logs p where p.work_order_id=wo.id),0) produced_qty,coalesce((select sum(rejection_qty) from production_logs p where p.work_order_id=wo.id),0) rejected_qty,coalesce((select string_agg(distinct pr.route_code,', ' order by pr.route_code) from rolling_plans x join process_routes pr on pr.id=x.process_route_id where x.work_order_id=wo.id),'') route,wo.target_date, greatest(0,wo.ordered_qty-coalesce((select sum(output_qty-rejection_qty) from production_logs p where p.work_order_id=wo.id and p.stage_id=(select id from process_stages where stage_code='FINISHING')),0)-coalesce((select sum(diverted_qty) from diversion_plans d where d.source_wo_id=wo.id),0)) total_pending,wo.status from work_orders wo left join rolling_plans rp on rp.work_order_id=wo.id group by wo.id;
create or replace view vw_dashboard_kpis as select count(*) filter(where status in ('Scheduled','In Progress')) active_work_orders,count(*) filter(where status='Pending Plan') pending_planning,count(*) filter(where status='Scheduled') scheduled_orders,count(*) filter(where status='In Progress') in_progress_orders,coalesce((select count(*) from production_logs where process_date=current_date and stage_id=(select id from process_stages where stage_code='FINISHING')),0) completed_today,coalesce((select sum(current_wip) from vw_route_stage_wip),0) total_wip,coalesce((select sum(rejection_qty) from production_logs),0) rejection_qty,count(*) filter(where target_date<current_date and total_pending>0) delayed_orders from vw_work_order_summary;
create or replace function audit_trigger() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into audit_log(user_id,action,entity,record_id,old_value,new_value) values(auth.uid(),tg_op,tg_table_name,coalesce(new.id,old.id),to_jsonb(old),to_jsonb(new)); return coalesce(new,old); end $$;
create trigger audit_work_orders after insert or update or delete on work_orders for each row execute function audit_trigger(); create trigger audit_rolling_plans after insert or update or delete on rolling_plans for each row execute function audit_trigger(); create trigger audit_diversions after insert or update or delete on diversion_plans for each row execute function audit_trigger(); create trigger audit_production after insert or update or delete on production_logs for each row execute function audit_trigger();
alter table profiles enable row level security; alter table process_stages enable row level security; alter table process_routes enable row level security; alter table route_stages enable row level security; alter table work_orders enable row level security; alter table rolling_plans enable row level security; alter table diversion_plans enable row level security; alter table production_logs enable row level security; alter table audit_log enable row level security;
create or replace function current_role() returns app_role language sql stable security definer set search_path=public as $$ select role from profiles where id=auth.uid(); $$;
create policy profile_self on profiles for select using(id=auth.uid());
create policy stages_read on process_stages for select to authenticated using(active or current_role()='Admin'); create policy routes_read on process_routes for select to authenticated using(active or current_role()='Admin'); create policy route_stages_read on route_stages for select to authenticated using(true);
create policy wo_read on work_orders for select to authenticated using(true); create policy wo_write on work_orders for all to authenticated using(current_role() in ('Admin','PPC')) with check(current_role() in ('Admin','PPC'));
create policy rp_read on rolling_plans for select to authenticated using(true); create policy rp_write on rolling_plans for all to authenticated using(current_role() in ('Admin','PPC')) with check(current_role() in ('Admin','PPC'));
create policy div_read on diversion_plans for select to authenticated using(true); create policy div_write on diversion_plans for insert to authenticated with check(current_role() in ('Admin','PPC'));
create policy prod_read on production_logs for select to authenticated using(true); create policy prod_write on production_logs for insert to authenticated with check(current_role() in ('Admin','Production','QA'));
create policy audit_read on audit_log for select to authenticated using(current_role() in ('Admin','PPC','QA'));
